def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # dp[i] will hold the length of the longest subsequence ending at index i
    max_len = 1

    for i in range(n):
        for j in range(i):
            if abs(nums[i] - nums[j]) >= abs(nums[j] - nums[j-1]) if j > 0 else True:
                dp[i] = max(dp[i], dp[j] + 1)
        max_len = max(max_len, dp[i])

    return max_len

def calculateScore(s: str) -> int:
    score = 0
    marked = set()
    mirrors = {chr(i): chr(219 - i) for i in range(97, 123)}  # Create a mirror mapping for a-z

    for i in range(len(s)):
        if i in marked:
            continue
        for j in range(i - 1, -1, -1):
            if j in marked:
                continue
            if mirrors[s[i]] == s[j]:
                score += i - j
                marked.add(i)
                marked.add(j)
                break
    return score

